function guardedEnemyTarget(t,precise=false,attacker=SOSText("combat_combat.guardedEnemyTarget.001")){if(!t||t.hp<=0||precise||t.trait==='shield')return t;const guard=combat.enemies.find(e=>e.hp>0&&e.trait==='shield');if(guard&&chance(.6)){combat.log.push(SOSText("combat_combat.guardedEnemyTarget.002",guard.name,attacker==='You'?'your attack':attacker+"'s attack",t.name));return guard}return t}
function strike(t,mult,accMod,critMod,opts={}){t=guardedEnemyTarget(t,!!opts.precise);const w=weapon(),hit=clamp(accuracy()+accMod,15,96),heavy=mult>=1.45;if(rnd(1,100)>hit){combat.log.push(SOSText("combat_combat.strike.001",t.name));sfxAttackForGuardian(false,t,heavy);return}let dmg=Math.max(1,Math.round((w.damage+damageBonus()+rnd(0,6))*mult));let critChance=5+Math.floor(stat(state,'dex')/3)+critMod+(w.id==='named_blade'?10:0);if(rnd(1,100)<=critChance){dmg=Math.round(dmg*1.65);combat.log.push(SOSText("combat_combat.strike.002"))}if(t.trait==='armored'||t.trait==='stone'||t.trait==='shield'){const reduction=t.armorBroken?.94:.82;dmg=Math.round(dmg*(weaponFamily(w)===SOSText("combat_combat.strike.003")?1.08:w.id==='named_hammer'?1.15:reduction))}if(w.id==='named_sword')dmg+=Math.floor(state.town.morale/20);t.hp-=dmg;combat.log.push(SOSText("combat_combat.strike.004",t.name,dmg));sfxAttackForGuardian(true,t,heavy)}
function allyTarget(m){const alive=combat.enemies.filter(e=>e.hp>0);if(!alive.length)return null;const priority=m.role==='archer'||m.role==='scout'?['healer','commander','mage','archer','engineer']:m.role==='defector'?['commander','elite','mage']:m.role==='spear'?['armored','stone','brute','shield']:m.role==='spawn'?['commander','brute','engineer']:[];for(const t of priority){const e=alive.find(x=>x.trait===t);if(e)return e}const chosen=activeTarget();return chosen&&chosen.hp>0?chosen:pick(alive)}
function allyHeal(m){const candidates=[{kind:'guardian',name:state.name,hp:state.guardian.hp,max:maxHP()},...partyMembers(true).filter(x=>x.id!==m.id).map(x=>({kind:'ally',member:x,name:x.name,hp:x.hp,max:allyMaxHP(x)}))].filter(x=>x.hp<x.max).sort((a,b)=>(a.hp<=0?0:1)-(b.hp<=0?0:1)||a.hp/a.max-b.hp/b.max);if(!candidates.length)return false;const target=candidates[0];if(target.hp>0&&target.hp>=target.max*.62)return false;const wasDown=target.hp<=0,amount=10+Math.floor(allyStat(m,'wis')*.7)+rnd(0,5)+allyClassBonus(m).healing+companionBonuses(m).healing;if(target.kind==='guardian')state.guardian.hp=Math.min(target.max,Math.max(0,state.guardian.hp)+amount);else target.member.hp=Math.min(target.max,Math.max(0,target.member.hp)+amount);combat.log.push(SOSText("combat_combat.allyHeal.001",m.name,wasDown?'revives':'tends',target.name,amount));return true}
function allyStrike(m,t,mult=1,accMod=0,label='hits'){t=guardedEnemyTarget(t,false,m.name);const w=allyWeapon(m),hit=clamp(allyAccuracy(m)+accMod+(combat.commandOrder==='focus'?10:0),25,97),heavy=mult>=1.4;if(rnd(1,100)>hit){combat.log.push(SOSText("combat_combat.allyStrike.001",m.name,t.name));sfxAttackForAlly(m,false,t,heavy);return}let dmg=Math.max(2,Math.round(((w.damage||6)+allyStat(m,'str')*.45+rnd(0,4)+allyClassBonus(m).damage+companionBonuses(m).damage)*mult));if(combat.commandOrder==='press')dmg=Math.round(dmg*1.15);if(m.role==='archer'||m.role==='scout')dmg+=2;if(m.role==='spear'&&['armored','stone','brute'].includes(t.trait))dmg+=4;if(m.role==='defector'&&t.trait==='commander')dmg+=4;if(t.trait==='armored'||t.trait==='stone'||t.trait==='shield')dmg=Math.round(dmg*(w.id==='named_hammer'?1.15:.86));t.hp-=dmg;combat.log.push(SOSText("combat_combat.allyStrike.002",m.name,label,t.name,dmg));sfxAttackForAlly(m,true,t,heavy)}
function allyWizardAttack(m,t,blast=false){const d=Math.max(5,Math.round(7+allyStat(m,'int')*.9+(m.level||1)*1.5+(blast?6:0)+rnd(0,4)));t.hp-=d;combat.log.push(SOSText("combat_combat.allyWizardAttack.001",m.name,blast?'Magical Blast':'Magical Bolt',t.name,d));sfxCombatAttack('magic',true,['armored','stone','shield'].includes(t.trait),blast)}
function allyTurn(){let allies=partyMembers(true).filter(m=>m.hp>0).sort((a,b)=>allyInitiative(b)-allyInitiative(a));if(combat.opening){const opp=allies.filter(m=>[SOSText("combat_combat.allyTurn.001"),SOSText("combat_combat.allyTurn.002")].includes(m.className||allyDef(m.id)?.className));if(opp.length)allies=[...opp,...allies.filter(m=>!opp.includes(m))]}for(const m of allies){if(combat.enemies.every(e=>e.hp<=0))break;if(m.skipNext){m.skipNext=false;combat.log.push(SOSText("combat_combat.allyTurn.003",m.name));continue}if(m.role==='healer'&&allyHeal(m))continue;let t=combat.opening?combat.enemies.find(e=>e.id===combat.opening.target&&e.hp>0):allyTarget(m);if(!t)t=allyTarget(m);if(!t)continue;const cls=m.className||allyDef(m.id)?.className;m.classRank=classRank(m.level||state.level);if(combat.opening&&[SOSText("combat_combat.allyTurn.004"),SOSText("combat_combat.allyTurn.005")].includes(cls)){allyStrike(m,t,cls===SOSText("combat_combat.allyTurn.006")?1.7:1.35,cls===SOSText("combat_combat.allyTurn.007")?16:20,cls===SOSText("combat_combat.allyTurn.008")?'exploits the opening against':SOSText("combat_combat.allyTurn.009"));combat.log.push(SOSText("combat_combat.allyTurn.010",m.name,t.name));combat.opening=null;t.stunned=0;continue}if([SOSText("combat_combat.allyTurn.011"),SOSText("combat_combat.allyTurn.012")].includes(cls)){const blast=m.stamina>=18&&chance(.32);allyWizardAttack(m,t,blast);if(blast)m.stamina-=18}else if([SOSText("combat_combat.allyTurn.013"),SOSText("combat_combat.allyTurn.014")].includes(cls)){if(m.stamina>=14&&chance(.38)){m.stamina-=14;allyStrike(m,t,.67,4,SOSText("combat_combat.allyTurn.015"));if(t.hp>0)allyStrike(m,t,.67,2,SOSText("combat_combat.allyTurn.016"))}else allyStrike(m,t)}else if([SOSText("combat_combat.allyTurn.017"),SOSText("combat_combat.allyTurn.018"),SOSText("combat_combat.allyTurn.019")].includes(cls)&&m.stamina>=14&&chance(.09)){m.stamina-=14;if(chance(.38)){allyStrike(m,t,.72,3,SOSText("combat_combat.allyTurn.020"));if(t.hp>0&&chance(.42)){t.stunned=1;combat.opening={target:t.id,type:'stunned'};combat.log.push(SOSText("combat_combat.allyTurn.021",m.name,t.name))}}else allyStrike(m,t,1.5,-10,SOSText("combat_combat.allyTurn.022"))}else allyStrike(m,t)}}
function showCombatItems(){modalRouteEnter(SOSText("combat_combat.showCombatItems.001"),Array.from(arguments));const usable=state.guardian.inventory.filter(v=>CONSUMABLES.some(c=>c.id===v.id));overlay(SOSText("combat_combat.showCombatItems.002",usable.map(v=>{const i=item(v.id);return `<button data-citem="${i.id}">${esc(i.name)} ×${v.qty} — ${esc(i.desc)}</button>`}).join('')||'<p>No usable items.</p>'),true);document.querySelectorAll('[data-citem]').forEach(b=>b.onclick=()=>['heal','bandage'].includes(b.dataset.citem)?showCombatHealTargets(b.dataset.citem):combatUseItem(b.dataset.citem,'guardian'));$('#backCombat').onclick=renderCombat}
function showCombatHealTargets(id){modalRouteEnter(SOSText("combat_combat.showCombatHealTargets.001"),Array.from(arguments));const targets=[['guardian',state.name,state.guardian.hp,maxHP()],...partyMembers(true).map(m=>[m.id,m.name,m.hp,allyMaxHP(m)])];overlay(SOSText("combat_combat.showCombatHealTargets.002",esc(item(id).name),targets.map(([tid,n,h,mx])=>`<button data-healtarget="${tid}" ${h>=mx?'disabled':''}>${esc(n)} — ${Math.max(0,h)}/${mx} HP${h<=0?' • DOWNED':''}</button>`).join('')));document.querySelectorAll('[data-healtarget]').forEach(b=>b.onclick=()=>combatUseItem(id,b.dataset.healtarget));$('#backItems').onclick=()=>SOSServices.navigation.back(showCombatItems)}
function combatUseItem(id,targetId='guardian'){const target=ownerFor(targetId),isG=targetId==='guardian';if(id==='antidote'&&!combat.poisoned){combat.log.push(SOSText("combat_combat.combatUseItem.001"));return renderCombat()}if(!target||!invRemove(id))return;if(id==='heal')target.hp=Math.min(isG?maxHP():allyMaxHP(target),Math.max(0,target.hp)+32);if(id==='bandage')target.hp=Math.min(isG?maxHP():allyMaxHP(target),Math.max(0,target.hp)+16);if(id==='stamina')state.guardian.stamina=Math.min(maxStamina(),state.guardian.stamina+35);if(id==='focus')combat.focus+=15;if(id==='stoneskin')combat.stoneskin=6;if(id==='swift')combat.swift=8;if(id==='bomb'){const t=activeTarget();const d=rnd(18,30);t.hp-=d;combat.log.push(SOSText("combat_combat.combatUseItem.002",t.name,d))}combat.log.push(SOSText("combat_combat.combatUseItem.003",item(id).name,['heal','bandage'].includes(id)?` on ${targetId==='guardian'?state.name:target.name}`:''));sfx('potion');if(combat.enemies.every(e=>e.hp<=0))return finishCombat(true);allyTurn();if(combat.enemies.every(e=>e.hp<=0))return finishCombat(true);enemyTurn()}
function enemyTargets(){const targets=[];if(state.guardian.hp>0)targets.push({kind:'guardian',name:state.name});for(const m of partyMembers(true).filter(m=>m.hp>0))targets.push({kind:'ally',name:m.name,member:m});return targets}
function commanderTactic(c,alive){const boss=alive.find(e=>e.boss);if(!boss||c.turn%3!==0)return null;const name=boss.name;if(boss.trait==='commander'){c.log.push(SOSText("combat_combat.commanderTactic.001",name));return{acc:7,dmg:3}}if(boss.trait==='engineer'){c.log.push(SOSText("combat_combat.commanderTactic.002",name));return{pierce:.25}}if(boss.trait==='duelist'){c.log.push(SOSText("combat_combat.commanderTactic.003",name));return{crit:.22}}if(boss.trait==='mage'){c.log.push(SOSText("combat_combat.commanderTactic.004",name));return{dmg:3,crit:.12}}return null}
function defenderDefense(t){return t.kind==='guardian'?defense()+(combat?.stoneskin||0):allyDefense(t.member)}
function effectiveDefenderDefense(t){return defenderDefense(t)+(combat?.guardianBrace&&t.kind==='guardian'?7:0)+(combat?.commandOrder==='hold'?4:0)}
function mitigateEnemyDamage(raw,target,pierce=0){
 raw=Math.max(1,Math.round(raw));
 const reduction=Math.max(0,Math.floor(effectiveDefenderDefense(target)*.55*(1-pierce)));
 const cappedReduction=Math.min(reduction,Math.floor(raw*.72));
 return Math.max(1,raw-cappedReduction)
}
function defenderHP(t){return t.kind==='guardian'?state.guardian.hp:t.member.hp}
function setDefenderHP(t,hp){if(t.kind==='guardian')state.guardian.hp=hp;else t.member.hp=hp}
function minimumEnemyDamage(e,target,tactic={},commander=false){let raw=e.damage-2+(commander?2:0)+(tactic.dmg||0);if(e.trait==='berserker'&&e.hp<e.maxHp/2)raw=Math.round(raw*1.35);const pierce=tactic.pierce&&e.boss?tactic.pierce:0;let dmg=mitigateEnemyDamage(raw,target,pierce);if(target.kind==='guardian'&&combat.defending)dmg=Math.ceil(dmg*.48);else if(target.kind==='ally'&&combat.companyGuard)dmg=Math.ceil(dmg*.72);return Math.max(1,dmg)}
function canSurviveMinimum(t,e,tactic,commander){return defenderHP(t)>minimumEnemyDamage(e,t,tactic,commander)}
function interposeChance(t,e){const isG=t.kind==='guardian',dex=isG?stat(state,'dex'):allyStat(t.member,'dex'),cls=isG?guardianClassBonus():allyClassBonus(t.member),hasShield=isG?!!state.guardian.equipment.offhand:!!t.member.equipment.offhand;return clamp(.52+(dex-e.init)*.025+(cls.interpose||0)+(hasShield?.1:0)+(isG&&combat?.swift?.08:0)+(!isG?companionBonuses(t.member).interpose:0),.2,.94)}
function resolveEnemyAttack(e,target,tactic={},commander=false){if(e.stunned){e.stunned=0;combat.log.push(SOSText("combat_combat.resolveEnemyAttack.001",e.name));return}if(combat.wardenGuard&&target.name===(combat.wardenGuard==='guardian'?state.name:ownerName(combat.wardenGuard))&&target.kind!=='guardian'&&state.guardian.hp>0&&chance(.78)){combat.log.push(SOSText("combat_combat.resolveEnemyAttack.002",target.name));target={kind:'guardian',name:state.name}}let acc=e.acc+(commander?6:0)+(tactic.acc||0)+(combat?.tactical?.enemyAcc||0)+(combat?.tactical?.terrain?.enemyAcc||0)-(e.waterSlow?10:0)-(e.airDisrupt?6:0)-(combat.reposition&&target.kind==='guardian'?12:0);if(rnd(1,100)>acc){combat.log.push(SOSText("combat_combat.resolveEnemyAttack.003",e.name,target.name));return}let raw=e.damage+rnd(-2,4)+(commander?2:0)+(tactic.dmg||0);if(e.trait==='berserker'&&e.hp<e.maxHp/2)raw=Math.round(raw*1.35);if((e.trait==='assassin'&&chance(.18))||(tactic.crit&&e.boss&&chance(tactic.crit))){raw=Math.round(raw*1.7);combat.log.push(SOSText("combat_combat.resolveEnemyAttack.004",e.name,target.name))}const pierce=tactic.pierce&&e.boss?tactic.pierce:0;let dmg=mitigateEnemyDamage(raw,target,pierce);if(target.kind==='guardian'&&combat.defending)dmg=Math.max(1,Math.ceil(dmg*.48));else if(target.kind==='ally'&&combat.companyGuard)dmg=Math.max(1,Math.ceil(dmg*.72));const before=defenderHP(target);setDefenderHP(target,before-dmg);if(target.kind==='guardian'&&guardianClass()===SOSText("combat_combat.resolveEnemyAttack.005"))combat.fury=clamp((combat.fury||0)+Math.max(6,Math.round(dmg/2)),0,100);combat.log.push(SOSText("combat_combat.resolveEnemyAttack.006",e.name,target.name,dmg));if(before>0&&defenderHP(target)<=0)combat.log.push(SOSText("combat_combat.resolveEnemyAttack.007",target.name))}
function automaticInterposer(target,e,tactic,commander){return enemyTargets().filter(t=>defenderId(t)!==defenderId(target)&&t.kind==='ally'&&canSurviveMinimum(t,e,tactic,commander)).sort((a,b)=>defenderHP(b)-defenderHP(a))[0]||null}
